          "教师：（讲述并出示小白兔图片）“今天，幼儿园开学了。小白兔起得特别早，她的脸上笑眯眯的，高高兴兴地去上幼儿园。”",
          "教师：（自问自答，模拟幼儿回答）小朋友们仔细看一看“小白兔的脸上是什么样的？请你来说一说。”（稍作停顿，做倾听状）“哦，你说笑眯眯的。观察的真仔细！小白兔是怎样去上幼儿园的呢？”",
          "教师：（肯定回应）好，你来说一说，“对，说得真清楚！它是高高兴兴地去上幼儿园。我们一起说：小白兔脸上笑眯眯地，高高兴兴去上幼儿园。”",
          "第二段：遇见小鸭子",
