          "教师：（模拟提问与互动）小朋友“是谁来了呀？大家都知道呀！小鸭子，它是怎么叫的？请你来学一学。”（模拟回答）“嘎嘎嘎，学得真像！小白兔见到小鸭子说了什么？”好，你来说。",
