          "教师：“小狗用什么办法？”请你来说，“对，用糨糊粘，可是粘不牢。” “小熊呢？”这次你来说，“没错，用绳子绑，可是绑不住。” “老爷爷的办法？”大家一起说，“滴些水，耳朵冻上了。”",
          "教师：“小冰兔最后又可以和朋友们快乐地玩啦！”"
