          "教师：“小朋友们表演得真棒！小冰兔有朋友帮助，耳朵终于冻上了。”",
          "教师：“今天，我们知道了水会结冰，也学会了朋友遇到困难要互相帮助。现在和小冰兔说再见吧！”"
