    "title": "小蚂蚁真有趣",
    "partLabels": {
      "process": "活动过程",
      "reflection": "活动反思"
    },
    "processBlocks": [
      {
        "heading": "（一）观察蚂蚁，情境导入（约1.5分钟）",
        "meta": "1.5分钟",
        "paragraphs": [
          "教师：（出示小蚂蚁图片）“小朋友们好！看，谁来了？对，小蚂蚁。仔细看一看小蚂蚁的头上有什么？“请你来说。” 哦，小蚂蚁头上有小须须。你观察的真仔细。那许多蚂蚁在一起是怎么走路的？谁看出来了。你来。",
          "教师：没错，排着队走。小眼睛真亮！”",
          "教师：“小蚂蚁见到好朋友会碰一碰小须须，还会一起搬大米。老师今天就带来一首关于小蚂蚁的儿歌《小蚂蚁真有趣》。”小朋友一起说儿歌的名字叫什么呀！对，小蚂蚁真有趣！"
        ]
      },
      {
        "heading": "（二）欣赏儿歌，理解内容（约3分钟）",
        "meta": "3分钟",
        "paragraphs": [
          "教师：请小朋友们竖起耳朵仔细听，瞪大眼睛认真看。（配合图谱朗诵）“小蚂蚁，真有趣，见面碰碰小须须；你碰我，我碰你，报告一个好消息；排队走，一二一，大家去抬一粒米。”",
          "教师：“儿歌里的小蚂蚁见面碰碰什么呀？”谁还记得，好，你来说。“对，小须须。你记得真清楚。我们伸出两只小手，来碰一碰小须须。”",
          "教师：猜一猜“它们碰一碰是在做什么？”请你来说。你说的是在打招呼、报告好消息。说的很好！请坐！最后小蚂蚁排着队去做什么了呀？”这个小朋友的小手举得最高你说吧！",
          "教师：（回应）“对，大家去抬一粒米。小蚂蚁人多力量大，真团结呀！”"
        ]
      },
      {
        "heading": "（三）分句学说，动作表现（约3分钟）",
        "meta": "3分钟",
        "paragraphs": [
          "教师：这首儿歌真有趣！我们看着图谱一句一句来学儿歌，小蚂蚁，真有趣，见面碰碰小须须。大家一起说一遍。小朋友伸出小手，和老师一起做碰须须的动作。”小朋友学的真像。",
          "教师：我们接着往下念，你碰我，我碰你，可以这样做动作，要轻轻的碰在一起；念到‘排队走，一二一’时，胳膊甩起来；念到‘大家去抬一粒米’时，两只小手一起抬。”",
          "教师：“现在看着图谱，我们边念儿歌边做动作完整的来朗诵儿歌。老师念一句，小朋友跟一句。小耳朵认真听，小嘴巴把每个字说清楚哟！” 小朋友的声音真好听！这次我们一起来朗诵诗歌，老师大声说，小朋友小声说，预备起，换过试一试，小朋友大声说，老师小声说。小朋友的声音真响亮。"
        ]
      },
      {
        "heading": "（四）蚂蚁搬米，自然结束（约2.5分钟）",
        "meta": "2.5分钟",
        "paragraphs": [
          "教师：现在我们来玩一个接龙的游戏，“老师说前半句，小朋友接后半句。看谁接的又快又准确。开始了啊，小蚂蚁——真有趣，见面碰碰——小须须。你碰我——我碰你，报告一个——好消息。排队走——一二一，大家去抬——一粒米。小朋友们接的真棒，我要加大难度了，敢不敢挑战，好，这次我说一句，小朋友接下一句，开始，",
          "小蚂蚁，真有趣——见面碰碰小须须。你碰我，我碰你——报告一个好消息。排队走，一二一——大家去抬一粒米。小朋友们太厉害了，挑战成功！",
          "教师：敢不敢挑战更难的，好！这次老师做动作，小朋友说儿歌。好！看仔细喽！教师：哇！你们太能干了，会看动作口齿清楚的说儿歌，真棒！”",
          "“现在我们来玩‘小蚂蚁搬米’游戏。请两位小朋友自由结合，先碰碰小须须、说一说好消息，再排着队一起把米粒送回家。”我们要边说儿歌边做动作哟！准备好了吗？开始。",
          "教师：“这一组小蚂蚁须须碰得轻轻的，这一组说‘一二一’说得很有节奏。大家一起抬米还会排队走，真像一群团结的小蚂蚁！”",
          "教师：“今天我们学会了儿歌《小蚂蚁真有趣》。回家后可以说给爸爸妈妈听，区域活动时，大家也可以用手偶继续念儿歌、玩小蚂蚁搬米游戏哟！”"
        ]
      }
    ],
    "reflectionBlocks": [
      {
        "heading": "活动反思",
        "meta": "完整内容",
        "paragraphs": [
          "依据《3—6岁儿童学习与发展指南》语言领域“倾听与表达”的要求，小班幼儿应愿意讲话、认真听别人讲话，喜欢跟读儿歌、童谣。本活动以节奏鲜明、动作性强的儿歌为载体，运用图谱和角色游戏支持理解，符合小班幼儿通过直接感知、实际操作和游戏学习的特点。",
          "目标达成与内容适宜性：儿歌句式短小、节奏性强，“碰碰小须须”“排队走，一二一”等语言与动作一一对应。幼儿可在观察、跟读和游戏中理解儿歌内容，学说重点短句，并体验小蚂蚁团结合作的意义。",
          "教学策略与师幼互动：通过“观察—朗诵—提问—动作示范—游戏”的路径逐步降低学习难度。不仅呈现了提问、等待、回应和提升的互动过程，还突出了对幼儿表达的支持。",
          "不足与改进：教学时，应接纳幼儿对蚂蚁的不同发现，并对语言较弱的幼儿提供图谱提示和同伴示范。合作搬米时，部分幼儿可能关注动作而忽略念说。后续可在语言区投放蚂蚁手偶和图谱，在餐前或过渡环节组织接龙朗诵，帮助幼儿在反复使用中巩固语言和合作经验。"
        ]
      }
    ],
