          "教师：“对，还是这三个小朋友；一开始是两个人一起玩、一个人独自坐着，后来变成三个人一起玩。现在请你按照图画顺序，把两幅图连起来讲一讲。”",
          "教师：“讲的时候可以先说‘开始……’，再说‘后来……’，最后说一说他们的心情。谁愿意来试一试？好，请你说。”（停顿，模拟倾听）",
          "教师：（复述、扩展幼儿表达）“开始，两个小朋友在一起玩，黑发男孩独自坐在旁边，不太开心。后来，他拿着一盘彩色玩具走过去，和两个小朋友一起玩。”你讲得很清楚，还用上了开始、‘后来’，真棒！",
          "教师：“谁还能加上他们说的话，让故事更有趣？这次请你来说一说。”（模拟回应）“黑发男孩问‘我能和你们一起玩吗’，两个小朋友回答‘好呀，咱们一起玩吧’，这样一讲，故事就像真的发生在我们面前一样。”礼貌的请求和友好的接纳会让大家都很开心。",
          "教师：（完整示范讲述）“小朋友说完了，老师也来说一说，开始，小女孩和蓝帽男孩在娃娃家一起玩。黑发男孩一个人坐在另一张桌子旁，托着下巴看着他们，心里有些难过。后来，他拿着一盘彩色玩具走过去，问：‘我能和你们一起玩吗？’两个小朋友笑着说：‘好呀，咱们一起玩吧！’最后，三个小朋友在一起玩得很开心。”"
