          "教师：（用稍慢语速完整讲述）《小熊吃西瓜》。夏天到了，熊哥哥和熊弟弟一起出去玩。它们看到一个大西瓜，熊哥哥摘下来用手一拍，西瓜变成两半。兄弟俩一人一半，坐在地上大口大口地吃，西瓜又甜又解渴！吃完后，熊弟弟把西瓜皮扣在头上，说“好凉快呀！”熊哥哥也学着戴上了西瓜帽。它们高高兴兴地回家了。",
